Pakai express-rate-limit + bcrypt + JWT. Contoh teruji:
```js
const rateLimit = require('express-rate-limit');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const limiter = rateLimit({ windowMs: 15*60*1000, max: 5, message: 'Terlalu banyak percobaan' });
app.post('/login', limiter, async (req, res) => {
  const { email, password } = req.body;
  if (!email || !password) return res.status(400).json({ error: 'email dan password wajib' });
  const user = await db.users.findOne({ email });
  if (!user || !(await bcrypt.compare(password, user.passwordHash))) {
    return res.status(401).json({ error: 'Kredensial salah' });
  }
  const token = jwt.sign({ sub: user.id }, process.env.JWT_SECRET, { expiresIn: '1h' });
  res.json({ token });
});
```
Jangan simpan password plain. Rate limit 5x / 15 menit.

