Express:
```js
function auth(req, res, next) {
  const h = req.headers.authorization || '';
  const token = h.startsWith('Bearer ') ? h.slice(7) : null;
  if (!token) return res.status(401).json({ error: 'Token wajib' });
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: 'Token tidak valid' });
  }
}
app.get('/me', auth, (req, res) => res.json({ id: req.user.sub }));
```
Pastikan JWT_SECRET kuat dan tidak di-commit.

CORS mengatur domain mana yang boleh memanggil API dari browser.
```js
const cors = require('cors');
app.use(cors({
  origin: ['https://app.kamu.com'],
  methods: ['GET','POST','PUT','DELETE'],
  credentials: true
}));
```
Jangan pakai `origin: '*'` + credentials sekaligus. Batasi origin production.

Batasi ukuran, tipe MIME, dan simpan di luar webroot.
```js
const multer = require('multer');
const upload = multer({
  limits: { fileSize: 2 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    if (!['image/jpeg','image/png'].includes(file.mimetype)) return cb(new Error('Tipe tidak diizinkan'));
    cb(null, true);
  }
});
app.post('/avatar', auth, upload.single('file'), (req, res) => {
  // simpan path, jangan pakai nama file dari client mentah
  res.json({ ok: true });
});
```

